(()=>{
const page=document.querySelector('.page'),items=[...document.querySelectorAll('.page [data-edit], .flip-hint[data-edit]')],toggle=document.querySelector('#toggle'),reset=document.querySelector('#reset'),sizeLabel=document.querySelector('#size-label'),size=document.querySelector('#size'),textButton=document.querySelector('#text-button'),input=document.querySelector('#text-input');
const key='nympheas-about-layout-v2';let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch{}if(saved._albumLayoutVersion!==2){delete saved['album-lace'];delete saved['album-strip'];delete saved['flip-hint'];saved._albumLayoutVersion=2;try{localStorage.setItem(key,JSON.stringify(saved))}catch{}}let editing=false,selected=null,drag=null;
function persist(){try{localStorage.setItem(key,JSON.stringify(saved))}catch{}}
document.querySelector('#export-layout').onclick=async()=>{const button=document.querySelector('#export-layout'),data=localStorage.getItem(key)||'{}';try{await navigator.clipboard.writeText(data);button.textContent='已複製 ✓'}catch{window.prompt('複製以下排版資料',data);button.textContent='請複製上方資料'}setTimeout(()=>button.textContent='複製排版資料',3000)};
function apply(el){const d=saved[el.dataset.edit];if(!d)return;if(d.x!=null)el.style.left=d.x+'%';if(d.y!=null)el.style.top=d.y+'%';if(d.w!=null)el.style.width=d.w+'%';if(d.s!=null)el.style.scale=d.s/100}
function styleDaydream(){const el=page.querySelector('[data-edit="metadata"]');if(!el||el.querySelector('.daydream'))return;const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){const i=node.data.indexOf('A little daydream');if(i<0)continue;const before=node.splitText(i),after=before.splitText('A little daydream'.length),em=document.createElement('em');em.className='daydream';em.textContent=before.data;before.replaceWith(em);return}}
function select(el){selected?.classList.remove('selected');selected=el;el.classList.add('selected');size.value=saved[el.dataset.edit]?.s||100;textButton.hidden=el.dataset.edit==='media';input.hidden=true}
items.forEach(el=>{if(saved[el.dataset.edit]?.html!=null)el.innerHTML=saved[el.dataset.edit].html});
styleDaydream();
for(const el of items){apply(el);const anchor=el.closest('.page')||page;for(const side of ['left','right']){const handle=document.createElement('span');handle.className='handle '+side;handle.setAttribute('role','slider');handle.setAttribute('aria-label',side==='left'?'拉動左邊界':'拉動右邊界');el.append(handle);handle.addEventListener('pointerdown',e=>{if(!editing)return;e.preventDefault();e.stopPropagation();select(el);const rect=el.getBoundingClientRect(),pr=anchor.getBoundingClientRect(),start=e.clientX;let x=100*(rect.left-pr.left)/pr.width,w=100*rect.width/pr.width;handle.setPointerCapture(e.pointerId);const move=ev=>{const delta=100*(ev.clientX-start)/pr.width;const d=saved[el.dataset.edit]||={};if(side==='left'){d.x=Math.max(1,Math.min(x+w-10,x+delta));d.w=Math.max(10,w-(d.x-x))}else d.w=Math.max(10,Math.min(99-x,w+delta));apply(el)};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',()=>{handle.removeEventListener('pointermove',move);persist()},{once:true})})}
el.addEventListener('pointerdown',e=>{if(!editing||e.target.closest('.handle'))return;e.preventDefault();e.stopPropagation();select(el);const r=el.getBoundingClientRect(),p=anchor.getBoundingClientRect();drag={el,id:e.pointerId,startX:e.clientX,startY:e.clientY,x:100*(r.left-p.left)/p.width,y:100*(r.top-p.top)/p.height};el.setPointerCapture(e.pointerId)});el.addEventListener('pointermove',e=>{if(!drag||drag.el!==el)return;const p=anchor.getBoundingClientRect(),d=saved[el.dataset.edit]||={};d.x=Math.max(0,Math.min(95,drag.x+100*(e.clientX-drag.startX)/p.width));d.y=Math.max(0,Math.min(95,drag.y+100*(e.clientY-drag.startY)/p.height));apply(el)});el.addEventListener('pointerup',()=>{if(drag){drag=null;persist()}})}
toggle.onclick=()=>{editing=!editing;document.body.classList.toggle('editing',editing);toggle.textContent=editing?'完成排版':'調整排版';reset.hidden=sizeLabel.hidden=!editing;textButton.hidden=!editing||!selected||selected.dataset.edit==='media';input.hidden=true;if(!editing){selected?.classList.remove('selected');selected=null}};
size.oninput=()=>{if(!selected)return;const d=saved[selected.dataset.edit]||={};d.s=+size.value;apply(selected);persist()};textButton.onclick=()=>{if(!selected)return;input.hidden=false;input.value=selected.innerText;input.focus()};input.oninput=()=>{if(!selected)return;const d=saved[selected.dataset.edit]||={};d.html=input.value.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('\n','<br>');const handles=[...selected.querySelectorAll('.handle')];selected.innerHTML=d.html;styleDaydream();selected.append(...handles);persist()};reset.onclick=()=>{saved={};localStorage.removeItem(key);location.reload()};
})();
